-- DMF0043_01 buttons
MERGE INTO SCM_ADM_MNU_BTN_MPG_M t USING (SELECT 'DMF0043_01' MNU_ID, 'main' SHT_NM, 'SEARCH' MNU_BTN_CD FROM DUAL) s
   ON (t.MNU_ID=s.MNU_ID AND t.SHT_NM=s.SHT_NM AND t.MNU_BTN_CD=s.MNU_BTN_CD)
 WHEN MATCHED THEN UPDATE SET API_ID='P_DMF0043_SALES_LIST_GET', USE_YN='Y', LAST_UPDATED_BY='admin', LAST_UPDATE_DATE=SYSDATE
 WHEN NOT MATCHED THEN INSERT (MNU_ID, SHT_NM, MNU_BTN_CD, API_ID, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
   VALUES ('DMF0043_01','main','SEARCH','P_DMF0043_SALES_LIST_GET','Y','admin',SYSDATE,'admin',SYSDATE);
